/* Assignment 3: pure FCFS and nearest-stop-first lift scheduling engine.
 * Each tick performs arrivals, deterministic assignment and one lift action.
 * FCFS preserves stop order; nearest re-evaluates remaining travel every tick.
 * Callbacks isolate live semaphore handshakes from testable scheduling logic. */
#include "core.h"
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

enum { ACT_IDLE='I',ACT_UP='U',ACT_DOWN='D',ACT_SERVE='S' };
void core_event(Core*c,const char*n,int p,int l){if(c->event_count>=MAX_EVENTS)return;CoreEvent*e=&c->events[c->event_count++];e->t=c->tick;e->passenger=p;e->lift=l;snprintf(e->name,sizeof e->name,"%s",n);}
static int stop_exists(const CoreLift*l,int kind,int floor){for(int i=0;i<l->stops_count;i++)if(l->stops[i].kind==kind&&l->stops[i].floor==floor)return 1;return 0;}
static void add_stop(CoreLift*l,int kind,int floor){if(stop_exists(l,kind,floor)||l->stops_count>=MAX_STOPS)return;l->stops[l->stops_count++]=(Stop){kind,floor};}
static void remove_stop(CoreLift*l,int kind,int floor){for(int i=0;i<l->stops_count;)if(l->stops[i].kind==kind&&l->stops[i].floor==floor){memmove(&l->stops[i],&l->stops[i+1],(size_t)(l->stops_count-i-1)*sizeof l->stops[0]);l->stops_count--;}else i++;}
static int target_index(const Core*c,int k){const CoreLift*l=&c->lift[k];if(!l->stops_count)return-1;if(c->policy==POLICY_FCFS){for(int i=0;i<l->stops_count;i++)if(!(l->riders>=c->scenario.capacity&&l->stops[i].kind==STOP_PICKUP))return i;return-1;}int best=-1,bd=0;for(int i=0;i<l->stops_count;i++){if(l->riders>=c->scenario.capacity&&l->stops[i].kind==STOP_PICKUP)continue;int d=l->stops[i].floor-l->floor;if(d<0)d=-d;if(best<0||d<bd){best=i;bd=d;}else if(d==bd){int dir=l->direction,di=l->stops[i].floor-l->floor,db=l->stops[best].floor-l->floor;int im=dir&&((di>0)-(di<0)==dir),bm=dir&&((db>0)-(db<0)==dir);if(im>bm||(im==bm&&l->stops[i].floor<l->stops[best].floor))best=i;}}return best;}
static int passenger_order(const CorePassenger*a,const CorePassenger*b){return(a->id>b->id)-(a->id<b->id);}
int core_init(Core*c,const Scenario*s,Policy p,CoreCallbacks cb){if(!c||!s)return-1;memset(c,0,sizeof*c);c->scenario=*s;c->policy=p;c->callbacks=cb;for(int i=0;i<s->lifts;i++){c->lift[i].floor=s->start[i];c->lift[i].last_target=-1;c->lift[i].last_action=ACT_IDLE;}for(int i=0;i<s->passenger_count;i++){c->passenger[i]=(CorePassenger){s->passenger[i].id,s->passenger[i].arrival,s->passenger[i].from,s->passenger[i].to,FUTURE,-1,-1,-1};}return 0;}
static void assign_waiting(Core*c){for(int order=0;order<c->scenario.passenger_count;order++){int slot=-1;for(int i=0;i<c->scenario.passenger_count;i++)if(c->passenger[i].state==WAITING&&c->passenger[i].lift<0&&(slot<0||passenger_order(&c->passenger[i],&c->passenger[slot])<0))slot=i;if(slot<0)break;CorePassenger*p=&c->passenger[slot];int best=0;for(int k=1;k<c->scenario.lifts;k++){if(c->policy==POLICY_FCFS){if(c->lift[k].stops_count<c->lift[best].stops_count)best=k;}else{int d=c->lift[k].floor-p->from;if(d<0)d=-d;int b=c->lift[best].floor-p->from;if(b<0)b=-b;if(d<b||(d==b&&(c->lift[k].stops_count<c->lift[best].stops_count||(c->lift[k].stops_count==c->lift[best].stops_count&&k<best))))best=k;}}p->lift=best;add_stop(&c->lift[best],STOP_PICKUP,p->from);core_event(c,"ASSIGN",p->id,best);}}
static int try_board(Core*c,int slot,int k){CoreLift*l=&c->lift[k];if(l->riders>=c->scenario.capacity)return 0;if(c->callbacks.board)return c->callbacks.board(c->callbacks.ctx,slot,k);return 1;}
static void serve(Core*c,int k,int kind,int floor){CoreLift*l=&c->lift[k];for(int idorder=0;idorder<c->scenario.passenger_count;idorder++){int slot=-1;for(int i=0;i<c->scenario.passenger_count;i++)if(c->passenger[i].state==RIDING&&c->passenger[i].lift==k&&c->passenger[i].to==floor&&(slot<0||c->passenger[i].id<c->passenger[slot].id))slot=i;if(slot<0)break;CorePassenger*p=&c->passenger[slot];if(c->callbacks.exit)c->callbacks.exit(c->callbacks.ctx,slot,k);p->state=DONE;p->deliver_tick=c->tick;l->riders--;c->delivered++;core_event(c,"DROP",p->id,k);}remove_stop(l,STOP_DROP,floor);
if(kind==STOP_PICKUP){for(int idorder=0;idorder<c->scenario.passenger_count;idorder++){int slot=-1;for(int i=0;i<c->scenario.passenger_count;i++)if(c->passenger[i].state==WAITING&&c->passenger[i].lift==k&&c->passenger[i].from==floor&&(slot<0||c->passenger[i].id<c->passenger[slot].id))slot=i;if(slot<0)break;if(!try_board(c,slot,k)){c->full_events++;core_event(c,"FULL",c->passenger[slot].id,k);break;}CorePassenger*p=&c->passenger[slot];p->state=RIDING;p->board_tick=c->tick;l->riders++;add_stop(l,STOP_DROP,p->to);core_event(c,"BOARD",p->id,k);}remove_stop(l,STOP_PICKUP,floor);for(int i=0;i<c->scenario.passenger_count;i++)if(c->passenger[i].state==WAITING&&c->passenger[i].lift==k&&c->passenger[i].from==floor){add_stop(l,STOP_PICKUP,floor);break;}}}
static void record_frame(Core*c,int actions[],int targets[]){if(c->frame_count>=MAX_TICKS)return;Frame*f=&c->frames[c->frame_count++];f->t=c->tick;for(int k=0;k<c->scenario.lifts;k++){LiftFrame*x=&f->lift[k];x->f=c->lift[k].floor;x->action=actions[k];x->target=targets[k];for(int i=0;i<c->scenario.passenger_count;i++)if(c->passenger[i].state==RIDING&&c->passenger[i].lift==k)x->riders[x->rider_count++]=c->passenger[i].id;}}
int core_step(Core*c){if(c->delivered==c->scenario.passenger_count)return 0;for(int i=0;i<c->scenario.passenger_count;i++)if(c->passenger[i].state==FUTURE&&c->passenger[i].arrival==c->tick){c->passenger[i].state=WAITING;core_event(c,"ARRIVE",c->passenger[i].id,-1);}assign_waiting(c);int progress=0,actions[MAX_LIFTS]={0},targets[MAX_LIFTS];for(int k=0;k<c->scenario.lifts;k++){CoreLift*l=&c->lift[k];int ti=target_index(c,k);targets[k]=ti<0?-1:l->stops[ti].floor;if(ti<0){actions[k]=ACT_IDLE;l->direction=0;}else{int target=l->stops[ti].floor;if(l->last_action==ACT_UP||l->last_action==ACT_DOWN){if(target!=l->last_target&&stop_exists(l,STOP_PICKUP,l->last_target)+stop_exists(l,STOP_DROP,l->last_target)>0){c->preempts++;core_event(c,"PREEMPT",-1,k);}}if(target==l->floor){int kind=l->stops[ti].kind;actions[k]=ACT_SERVE;serve(c,k,kind,target);progress=1;}else{l->direction=target>l->floor?1:-1;actions[k]=l->direction>0?ACT_UP:ACT_DOWN;if(!l->riders)c->empty_moves++;c->move_actions++;l->floor+=l->direction;progress=1;}l->last_target=target;}l->last_action=actions[k];c->load_sum+=l->riders;c->lift_ticks++;}record_frame(c,actions,targets);int active=0;for(int i=0;i<c->scenario.passenger_count;i++)if(c->passenger[i].state==WAITING||c->passenger[i].state==RIDING)active=1;if(active&&!progress)c->stuck_ticks++;else c->stuck_ticks=0;c->tick++;return c->stuck_ticks>=50?-2:1;}
int core_run(Core*c,int max){while(c->delivered<c->scenario.passenger_count&&c->tick<max){int r=core_step(c);if(r<0)return r;}return c->delivered==c->scenario.passenger_count?0:-1;}
void core_metrics(const Core*c,Metrics*m){memset(m,0,sizeof*m);m->delivered=c->delivered;m->preempts=c->preempts;m->full_events=c->full_events;for(int i=0;i<c->scenario.passenger_count;i++){const CorePassenger*p=&c->passenger[i];if(p->state==DONE){m->avg_wait+=p->board_tick-p->arrival;m->avg_ride+=p->deliver_tick-p->board_tick;m->avg_total+=p->deliver_tick-p->arrival;if(p->deliver_tick>m->makespan)m->makespan=p->deliver_tick;}}if(c->delivered){m->avg_wait/=c->delivered;m->avg_ride/=c->delivered;m->avg_total/=c->delivered;}if(c->move_actions)m->empty_move_pct=100.0*c->empty_moves/c->move_actions;if(c->lift_ticks)m->avg_load_pct=100.0*c->load_sum/(c->lift_ticks*c->scenario.capacity);}
int core_validate(const Core*c,char*err,unsigned z){for(int i=0;i<c->scenario.passenger_count;i++){const CorePassenger*p=&c->passenger[i];if(p->state!=DONE){snprintf(err,z,"passenger %d not delivered",p->id);return-1;}if(!(p->deliver_tick>p->board_tick&&p->board_tick>=p->arrival)){snprintf(err,z,"passenger %d invalid timing",p->id);return-1;}}for(int f=0;f<c->frame_count;f++)for(int k=0;k<c->scenario.lifts;k++){if(c->frames[f].lift[k].rider_count>c->scenario.capacity){snprintf(err,z,"capacity exceeded");return-1;}if(f&&abs(c->frames[f].lift[k].f-c->frames[f-1].lift[k].f)>1){snprintf(err,z,"lift moved more than one floor");return-1;}}return 0;}
